export const LOGO_PNG_BUFFER = Buffer.from(LOGO_PNG_BASE64, "base64");

export function getLogoAttachment() {
  return {
    filename: "logo.png",
    content: LOGO_PNG_BUFFER,
    contentType: "image/png",
    cid: LOGO_CID,
    contentDisposition: "inline",
  };
}

export async function embedLogoPng(pdf) {
  return pdf.embedPng(LOGO_PNG_BUFFER);
}
